const input = $('Execute Sub Workflow Trigger').first().json;
const prev = items[0].json;

// V1-V4 complete. Workflow will now pause at V5 Wait node.
// Operator must complete DaVinci Resolve editing, then POST to resume webhook.
return [{json: {
  ...input,
  ...prev,
  v5_status: 'awaiting_manual_edit',
  v5_message: 'V1-V4 automated steps complete. Proxy files ready in video/proxy/. Open DaVinci Resolve project, complete color grading and editing, export masters to video/master/. Then POST to the resume webhook URL to continue V6 export and delivery.',
  v5_resume_info: 'POST to {N8N_BASE_URL}/webhook-waiting/{executionId}/v5-resolve-complete to resume'
}}];

const input = $('V5 Gate Setup').first().json;

// After Wait resumes, check if video/master/ has content (informational only)
// V6 will error if master files are missing, so we just log a warning here
return [{json: {
  ...input,
  v5_status: 'resumed',
  v5_resume_note: 'DaVinci Resolve edit marked complete by operator. Proceeding to V6 format export.'
}}];

